using System.Globalization;

namespace TopSpin4.Launcher.Core;

/// <summary>One file an input holds: its path ('/' separators), size and SHA-256.</summary>
public sealed record ManifestEntry(string Path, long Size, string Sha256);

/// <summary>
/// The files of one Reference build input with their sizes and SHA-256s, no data: the disc's
/// game partition (<c>launcher/disc-manifest.tsv</c>) or the TU1 package
/// (<c>launcher/tu1-manifest.tsv</c>), both generated by <c>scripts/write_manifests.py</c> and
/// embedded. Format: <c>#</c> comments, one <c>manifest_version&lt;TAB&gt;id</c> line, then
/// <c>sha256&lt;TAB&gt;size&lt;TAB&gt;path</c> per file.
/// </summary>
public sealed class FileManifest
{
    private readonly Dictionary<string, ManifestEntry> _byPath;

    private FileManifest(string version, IReadOnlyList<ManifestEntry> files)
    {
        Version = version;
        Files = files;
        _byPath = files.ToDictionary(file => file.Path, StringComparer.OrdinalIgnoreCase);
    }

    /// <summary>Names the manifest; a prepared folder's marker records it.</summary>
    public string Version { get; }
    public IReadOnlyList<ManifestEntry> Files { get; }
    public long TotalBytes => Files.Sum(file => file.Size);

    public ManifestEntry? Find(string path) => _byPath.GetValueOrDefault(path);

    /// <summary>The Reference build's disc: media 60819732, every Module v0.0.0.3.</summary>
    public static FileManifest Disc { get; } = LoadEmbedded("disc-manifest.tsv");

    /// <summary>Title Update 1 for that disc, which raises every Module to v0.0.1.3.</summary>
    public static FileManifest TitleUpdate { get; } = LoadEmbedded("tu1-manifest.tsv");

    public static FileManifest Parse(string text)
    {
        string? version = null;
        var files = new List<ManifestEntry>();
        foreach (var raw in text.Split('\n'))
        {
            var line = raw.TrimEnd('\r');
            if (line.Length == 0 || line[0] == '#') continue;
            var parts = line.Split('\t');
            if (parts is ["manifest_version", var id] && version is null && id.Length > 0) version = id;
            else if (parts.Length == 3 && parts[0].Length == 64
                     && long.TryParse(parts[1], NumberStyles.None, CultureInfo.InvariantCulture, out var size)
                     && parts[2].Length > 0)
                files.Add(new ManifestEntry(parts[2], size, parts[0].ToLowerInvariant()));
            else throw new InvalidDataException("The manifest has a malformed line: " + line);
        }
        if (version is null) throw new InvalidDataException("The manifest has no manifest_version line.");
        return new FileManifest(version, files);
    }

    private static FileManifest LoadEmbedded(string name)
    {
        using var stream = typeof(FileManifest).Assembly.GetManifestResourceStream(name)
            ?? throw new InvalidOperationException($"The manifest {name} is not embedded in the launcher.");
        using var reader = new StreamReader(stream);
        return Parse(reader.ReadToEnd());
    }
}
